mapper.select:
SELECT GROUP_ID, OWNER_ID, STATUS
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT GYE_MEMBER_ID, GROUP_ID, MEMBER_ID, STATUS, PAYOUT_RECEIVED_YN
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}

SELECT COUNT(*)
FROM WITHDRAWAL_REQUEST
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS IN ('SETTLEMENT_PENDING', 'CONSENT_PENDING')

mapper.update:
UPDATE WITHDRAWAL_REQUEST
SET SETTLEMENT_AMOUNT = #{settlementAmount},
    SETTLEMENT_MEMO   = #{settlementMemo},
    SETTLEMENT_BY     = #{leaderId},
    SETTLEMENT_AT     = SYSDATE,
    STATUS            = 'CONSENT_PENDING'
WHERE GROUP_ID = #{groupId}
  AND WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}
  AND STATUS = #{expectedStatus}

mapper.delete:
DELETE FROM CONSENT
WHERE CONSENT_TYPE = 'SETTLEMENT'
  AND TARGET_ID = #{withdrawalRequestId}

mapper.insert:
INSERT INTO WITHDRAWAL_CONSENT_TARGET (
    WITHDRAWAL_REQUEST_ID, GROUP_ID, MEMBER_ID, STATUS, CREATED_AT
)
SELECT #{withdrawalRequestId}, gm.GROUP_ID, gm.MEMBER_ID, 'PENDING', SYSDATE
FROM GYE_MEMBER gm
WHERE gm.GROUP_ID = #{groupId}
  AND gm.STATUS = 'ACTIVE'
  AND gm.MEMBER_ID != #{applicantId}

mapper.select:
SELECT GYE_MEMBER_ID, GROUP_ID, MEMBER_ID, STATUS, PAYOUT_RECEIVED_YN
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
FOR UPDATE

mapper.update:
UPDATE WITHDRAWAL_CONSENT_TARGET
SET STATUS = #{status},
    RESPONDED_AT = SYSDATE
WHERE WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}
  AND GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'PENDING'

UPDATE WITHDRAWAL_CONSENT_TARGET
SET STATUS = 'EXEMPT',
    EXEMPTED_BY = #{adminId},
    EXEMPTED_AT = SYSDATE,
    EXEMPTION_REASON = #{reason}
WHERE WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}
  AND GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'PENDING'
  AND EXISTS (
      SELECT 1
      FROM GYE_MEMBER gm
      WHERE gm.GROUP_ID = #{groupId}
        AND gm.MEMBER_ID = #{memberId}
        AND gm.STATUS = 'ACTIVE'
  )

mapper.select:
SELECT COUNT(*)
FROM WITHDRAWAL_CONSENT_TARGET
WHERE WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}

mapper.update:
UPDATE WITHDRAWAL_REQUEST
SET RECONFIRM_COUNT = RECONFIRM_COUNT + 1
WHERE WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}

UPDATE WITHDRAWAL_REQUEST
SET STATUS = #{status},
    DECIDED_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}
  AND STATUS = #{expectedStatus}

UPDATE GYE_MEMBER
SET STATUS  = 'WITHDRAWN',
    LEFT_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'ACTIVE'

mapper.select:
SELECT MEMBER_ID
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{excludeMemberId}
